+        preferenceTelemetry.registerPrefObservers();
         reportUIConfiguration();
         reportEwsAccounts();
       },
@@ -1368,8 +1370,8 @@ async function reportCalendars() {
  * Note: These probes can handle up to 100 labels each. If you add a preference
