   reportAccountPreferences,
   reportAddressBookTypes,
   reportCalendars,
-  reportPreferences,
+  reportPreferences: () => new PreferenceTelemetry().reportPreferences(),
   reportUIConfiguration,
   reportEwsAccounts,
 };
